@Model
final class Trip {
    var destination: String?
    var end_date: Date?
    var name: String?
    var start_date: Date?

    @Relationship(.cascade)
    var bucketListItem: [BucketListItem] = [BucketListItem]()

    @Relationship(.cascade)
    var livingAccommodation: LivingAccommodation?
}

// ModelContainer initialized with just Trip
